import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

export default function Login() {
  const [email, setEmail]       = useState('');
  const [password, setPassword] = useState('');
  const [showPwd, setShowPwd]   = useState(false);
  const [error, setError]       = useState('');
  const [loading, setLoading]   = useState(false);
  const { login }  = useAuth();
  const navigate   = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      await login(email, password);
      navigate('/');
    } catch {
      setError('Email ou mot de passe incorrect');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={S.page}>
      {/* Panneau gauche */}
      <div style={S.left}>
        <div style={S.leftInner}>
          {/* Logo */}
          <div style={S.logoRow}>
            <div style={S.logoIcon}>
              <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#00d4aa" strokeWidth="1.8">
                <rect x="2" y="7" width="20" height="14" rx="2"/>
                <path d="M16 7V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v2"/>
                <line x1="12" y1="12" x2="12" y2="16"/>
                <line x1="10" y1="14" x2="14" y2="14"/>
              </svg>
            </div>
            <span style={S.logoText}>INDUSTRIOT</span>
          </div>

          {/* Titre principal */}
          <div style={S.leftTitle}>
            Supervision<br/>
            <span style={S.leftTitleAccent}>Industrielle IoT</span>
          </div>
          <div style={S.leftDesc}>
            Plateforme unifiée de monitoring, contrôle et analyse de vos équipements industriels en temps réel.
          </div>

          {/* Stats */}
          <div style={S.statsRow}>
            {[
              { val:'99.9%', label:'Disponibilité' },
              { val:'<1s',   label:'Latence'       },
              { val:'24/7',  label:'Monitoring'    },
            ].map(s => (
              <div key={s.label} style={S.statItem}>
                <div style={S.statVal}>{s.val}</div>
                <div style={S.statLabel}>{s.label}</div>
              </div>
            ))}
          </div>

          {/* Features */}
          <div style={S.features}>
            {[
              { icon: <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#00d4aa" strokeWidth="1.8"><polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/></svg>, label:'Mesures temps réel' },
              { icon: <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#00d4aa" strokeWidth="1.8"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>, label:'Alertes intelligentes' },
              { icon: <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#00d4aa" strokeWidth="1.8"><circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M4.22 4.22l2.12 2.12M17.66 17.66l2.12 2.12M2 12h3M19 12h3M4.22 19.78l2.12-2.12M17.66 6.34l2.12-2.12"/></svg>, label:'Contrôle des relais' },
              { icon: <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#00d4aa" strokeWidth="1.8"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/></svg>, label:'Gestion des équipes' },
            ].map(f => (
              <div key={f.label} style={S.featureItem}>
                <div style={S.featureIcon}>{f.icon}</div>
                <span style={S.featureLabel}>{f.label}</span>
              </div>
            ))}
          </div>

          {/* Illustration réseau IoT */}
          <div style={S.illustration}>
            <svg viewBox="0 0 320 160" fill="none" xmlns="http://www.w3.org/2000/svg" style={{width:'100%'}}>
              <defs>
                <pattern id="dots" width="16" height="16" patternUnits="userSpaceOnUse">
                  <circle cx="1" cy="1" r="0.8" fill="rgba(0,212,170,0.12)"/>
                </pattern>
              </defs>
              <rect width="320" height="160" fill="url(#dots)"/>

              {/* Nœuds machines */}
              {[
                { cx:40,  cy:80,  r:18, color:'#00d4aa', label:'M1' },
                { cx:120, cy:40,  r:14, color:'#0099ff', label:'M2' },
                { cx:120, cy:120, r:14, color:'#f5a623', label:'M3' },
                { cx:200, cy:65,  r:16, color:'#00d4aa', label:'M4' },
                { cx:200, cy:110, r:12, color:'#a855f7', label:'M5' },
                { cx:280, cy:80,  r:20, color:'#00d4aa', label:'HUB' },
              ].map(n => (
                <g key={n.label}>
                  <circle cx={n.cx} cy={n.cy} r={n.r + 6} fill={`${n.color}08`}/>
                  <circle cx={n.cx} cy={n.cy} r={n.r} fill={`${n.color}15`} stroke={n.color} strokeWidth="1.2"/>
                  <text x={n.cx} y={n.cy + 4} textAnchor="middle" fontSize="8" fill={n.color} fontFamily="monospace" fontWeight="600">{n.label}</text>
                </g>
              ))}

              {/* Connexions */}
              {[
                [40,80, 120,40],  [40,80, 120,120],
                [120,40, 200,65], [120,120, 200,110],
                [200,65, 280,80], [200,110, 280,80],
              ].map(([x1,y1,x2,y2], i) => (
                <line key={i} x1={x1} y1={y1} x2={x2} y2={y2}
                  stroke="rgba(0,212,170,0.20)" strokeWidth="1" strokeDasharray="4 3"/>
              ))}

              {/* Données qui voyagent */}
              {[
                { x:40, y:80, dx:120, dy:40, color:'#00d4aa' },
                { x:200, y:65, dx:280, dy:80, color:'#0099ff' },
              ].map((d, i) => (
                <circle key={i} r="2.5" fill={d.color} opacity="0.8">
                  <animateMotion dur={`${2 + i}s`} repeatCount="indefinite"
                    path={`M${d.x},${d.y} L${d.dx},${d.dy}`}/>
                </circle>
              ))}

              {/* Courbe signal */}
              <path d="M 10 145 Q 40 130 70 140 Q 100 150 130 132 Q 160 114 190 128 Q 220 142 250 125 Q 280 108 310 118"
                stroke="rgba(0,212,170,0.40)" strokeWidth="1.5" fill="none"/>
              <path d="M 10 145 Q 40 130 70 140 Q 100 150 130 132 Q 160 114 190 128 Q 220 142 250 125 Q 280 108 310 118 L 310 160 L 10 160 Z"
                fill="rgba(0,212,170,0.04)"/>
            </svg>
          </div>
        </div>
      </div>

      {/* Panneau droit */}
      <div style={S.right}>
        <div style={S.formWrap}>
          {/* En-tête formulaire */}
          <div style={S.formHeader}>
            <div style={S.formLogoSmall}>INDUSTRIOT</div>
            <h2 style={S.formTitle}>Connexion</h2>
            <p style={S.formSub}>Accédez à votre espace de supervision</p>
          </div>

          {/* Erreur */}
          {error && (
            <div style={S.errorBox}>
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#ff4757" strokeWidth="2" style={{flexShrink:0}}>
                <circle cx="12" cy="12" r="10"/>
                <line x1="12" y1="8" x2="12" y2="12"/>
                <line x1="12" y1="16" x2="12.01" y2="16"/>
              </svg>
              {error}
            </div>
          )}

          {/* Formulaire */}
          <form onSubmit={handleSubmit} style={{width:'100%'}}>
            <div style={S.fieldWrap}>
              <label style={S.label}>ADRESSE EMAIL</label>
              <div style={S.inputGroup}>
                <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#4a5260" strokeWidth="1.8" style={S.inputSvg}>
                  <path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/>
                  <polyline points="22,6 12,13 2,6"/>
                </svg>
                <input
                  style={S.input}
                  type="email"
                  value={email}
                  onChange={e => setEmail(e.target.value)}
                  placeholder=""
                  required
                />
              </div>
            </div>

            <div style={S.fieldWrap}>
              <label style={S.label}>MOT DE PASSE</label>
              <div style={S.inputGroup}>
                <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#4a5260" strokeWidth="1.8" style={S.inputSvg}>
                  <rect x="3" y="11" width="18" height="11" rx="2" ry="2"/>
                  <path d="M7 11V7a5 5 0 0 1 10 0v4"/>
                </svg>
                <input
                  style={S.input}
                  type={showPwd ? 'text' : 'password'}
                  value={password}
                  onChange={e => setPassword(e.target.value)}
                  placeholder="••••••••"
                  required
                />
                <button type="button" style={S.eyeBtn} onClick={() => setShowPwd(!showPwd)}>
                  {showPwd ? (
                    <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#7a8394" strokeWidth="1.8">
                      <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94"/>
                      <path d="M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19"/>
                      <line x1="1" y1="1" x2="23" y2="23"/>
                    </svg>
                  ) : (
                    <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#7a8394" strokeWidth="1.8">
                      <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/>
                      <circle cx="12" cy="12" r="3"/>
                    </svg>
                  )}
                </button>
              </div>
            </div>

            <button style={{...S.submitBtn, opacity: loading ? 0.75 : 1}} type="submit" disabled={loading}>
              {loading ? (
                <span style={{display:'flex', alignItems:'center', justifyContent:'center', gap:10}}>
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" style={{animation:'spin 0.8s linear infinite'}}>
                    <path d="M21 12a9 9 0 1 1-6.219-8.56"/>
                  </svg>
                  Connexion en cours...
                </span>
              ) : (
                <span style={{display:'flex', alignItems:'center', justifyContent:'center', gap:8}}>
                  Se connecter
                  <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                    <line x1="5" y1="12" x2="19" y2="12"/>
                    <polyline points="12 5 19 12 12 19"/>
                  </svg>
                </span>
              )}
            </button>
          </form>

          {/* Footer */}
          <div style={S.formFooter}>
            <div style={S.footerLine}/>
            <span style={S.footerText}>Accès restreint · Personnel autorisé uniquement</span>
            <div style={S.footerLine}/>
          </div>
       
        </div>
      </div>

      <style>{`
        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
        input::placeholder { color: #3a4050; }
        input:focus { border-color: rgba(0,212,170,0.40) !important; box-shadow: 0 0 0 3px rgba(0,212,170,0.06); }
      `}</style>
    </div>
  );
}

